'use strict';
const C=KPAPContract, esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let graphSpec,card,configs,selected='answer',snapshot=null,contractError='',importText='',input='반품 배송비는 얼마인가요?',scenario='normal',loading=true;
const app=document.querySelector('#sdk-app');
const pretty=x=>esc(JSON.stringify(x,null,2));
async function loadExample(){loading=true;render();try{const responses=await Promise.all(['fixtures/support-agent.graph.json','fixtures/agent-card.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw new Error('예제 조회 실패: '+r.status);return r.json();}));card=responses[1];applyGraph(responses[0]);}catch(e){contractError=e.message;}finally{loading=false;render();}}
function applyGraph(g){const checked=C.validateGraph(g);graphSpec=checked;configs=C.resolve(checked);selected=checked.nodes.find(n=>(n.editable||[]).length)?.id||checked.nodes[0].id;snapshot=null;contractError='';importText=JSON.stringify(g,null,2);}
function graphView(){
 const g=graphSpec,rank=Object.fromEntries(g.nodes.map(n=>[n.id,0]));
 // A bounded layout pass ignores explicit back edges; cycles never drive execution.
 for(let i=0;i<Math.min(g.nodes.length,6);i++)for(const e of g.edges)if(!['loop'].includes(e.kind)&&e.source!==e.target)rank[e.target]=Math.min(6,Math.max(rank[e.target],rank[e.source]+1));
 const groups={};g.nodes.forEach(n=>(groups[rank[n.id]]||=[]).push(n));const pos={},width=Math.max(600,...Object.values(groups).map(ns=>ns.length*210)),height=(Math.max(...Object.values(rank))+1)*130+30;
 Object.entries(groups).forEach(([r,ns])=>ns.forEach((n,i)=>pos[n.id]={x:(i+1)*width/(ns.length+1),y:35+Number(r)*130}));
 const edges=g.edges.map(e=>{const a=pos[e.source],b=pos[e.target],back=b.y<=a.y;const d=back?`M${a.x+80} ${a.y+25} C${a.x+160} ${a.y-70},${b.x+160} ${b.y-70},${b.x+80} ${b.y+25}`:`M${a.x} ${a.y+55} C${a.x} ${a.y+90},${b.x} ${b.y-35},${b.x} ${b.y}`;return `<path class="contract-edge ${esc(e.kind||'normal')}" d="${d}" marker-end="url(#sdk-arrow)"/><text x="${(a.x+b.x)/2+8}" y="${(a.y+b.y)/2+24}" class="edge-label">${esc(e.label||e.kind==='loop'&&'반복'||'')}</text>`;}).join('');
 return `<div class="sdk-graph"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="조회한 그래프의 노드와 연결"><defs><marker id="sdk-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10" fill="#91a99b"/></marker></defs>${edges}${g.nodes.map(n=>{const p=pos[n.id];return `<g class="contract-node ${selected===n.id?'selected':''}" tabindex="0" role="button" aria-label="${esc(n.name||n.id)} 선택" data-node="${esc(n.id)}"><rect x="${p.x-80}" y="${p.y}" width="160" height="55" rx="10"/><text x="${p.x}" y="${p.y+23}" text-anchor="middle">${esc(n.name||n.id)}</text><text class="node-kind" x="${p.x}" y="${p.y+42}" text-anchor="middle">${esc(n.type+(n.parentId?' · '+n.parentId:''))}</text></g>`;}).join('')}</svg></div><div class="sdk-node-list" aria-label="노드 목록">${g.nodes.map(n=>`<button class="btn small ${selected===n.id?'active':''}" data-node="${esc(n.id)}">${esc(n.name||n.id)}</button>`).join('')}</div>`;
}
function control(path,s,v,disabled){const attr=`data-path="${esc(JSON.stringify(path))}" ${disabled?'disabled':''}`;const label=({'model':'모델','prompt':'프롬프트 본문','tools':'허용 도구','knowledge':'지식','resourceId':'지식 자원','version':'자원 버전','topK':'검색 수'})[path.at(-1)]||path.at(-1),id='edit-'+path.join('-');
 if(s.type==='object')return `<fieldset><legend>${esc(label)}</legend>${Object.entries(s.properties).map(([k,child])=>control([...path,k],child,v?.[k],disabled)).join('')}</fieldset>`;
 let html;if(s.type==='array')html=`<textarea id="${id}" ${attr} data-json="true" rows="3">${esc(JSON.stringify(v))}</textarea><p class="hint">JSON 배열 · []는 모두 해제${s.items.enum?' · 허용: '+esc(s.items.enum.join(', ')):''}</p>`;
 else if(s.enum)html=`<select id="${id}" ${attr}>${s.enum.map(x=>`<option value="${esc(x)}" ${x===v?'selected':''}>${esc(x)}</option>`).join('')}</select>`;
 else if(s.type==='boolean')html=`<input id="${id}" type="checkbox" ${attr} ${v?'checked':''}>`;
 else if(['integer','number'].includes(s.type))html=`<input id="${id}" type="number" ${attr} value="${esc(v)}" ${s.minimum!==undefined?'min="'+s.minimum+'"':''} ${s.maximum!==undefined?'max="'+s.maximum+'"':''}>`;
 else html=`<textarea id="${id}" ${attr} rows="${path[0]==='prompt'?5:2}">${esc(v)}</textarea>`;
 return `<div class="field"><label for="${id}">${esc(label)}</label>${html}</div>`;
}
function requestPreview(){try{return C.buildRequest(graphSpec,configs,input);}catch(e){return {error:e.code,path:e.path,message:e.message};}}
function render(){
 const n=graphSpec?.nodes.find(n=>n.id===selected);
 app.innerHTML=`<div class="titlebar"><div class="agent-title"><span class="agent-logo">◈</span><h1>SDK 연동</h1><span class="demo-label">계약 검증 데모</span></div><div class="actions"><a class="btn" href="index.html">작업공간으로</a><button class="btn" id="reload" ${loading?'disabled':''}>예제 다시 읽기</button></div></div><div class="sdk-intro"><strong>그래프를 읽고, 노드 설정을 바꿔 실행 요청을 검증합니다.</strong><p>예제는 SDK 응답 형식의 정적 JSON입니다. 검증·설정 적용은 브라우저에서 모의 수행하며 실제 모델·도구·지식은 호출하지 않습니다.</p></div>${contractError?`<p class="form-error sdk-error" role="alert">${esc(contractError)}</p>`:''}${graphSpec?`<div class="sdk-summary"><span>${esc(graphSpec.agentId)} · ${esc(graphSpec.version)}</span><span>노드 ${graphSpec.nodes.length} · 연결 ${graphSpec.edges.length} · 규격 ${esc(graphSpec.schemaVersion)}</span></div><div class="sdk-workspace"><section class="panel"><div class="panel-head"><h2>1. 조회한 흐름</h2><span class="hint">구조 읽기 전용</span></div>${graphView()}</section><section class="panel"><div class="panel-head"><h2>2. ${esc(n.name||n.id)}</h2><button class="btn small" id="restore">기본값 복구</button></div><div class="panel-body">${n.configSchema?Object.entries(n.configSchema.properties).map(([k,s])=>control([k],s,configs[n.id][k],!(n.editable||[]).includes(k))).join(''):'<p class="hint">공개 설정이 없는 노드입니다.</p>'}<p class="hint">변경값은 이번 요청에만 적용합니다. 기본 그래프는 보존합니다.</p></div></section><section class="panel"><div class="panel-head"><h2>3. 요청·적용 확인</h2></div><div class="panel-body"><div class="field"><label for="sdk-input">고객 입력</label><textarea id="sdk-input" rows="3">${esc(input)}</textarea></div><div class="field"><label for="scenario">검증 상황</label><select id="scenario">${[['normal','정상 적용'],['version','그래프 버전 충돌'],['permission','자원 권한 거부'],['extension','확장 헤더 누락']].map(([id,name])=>`<option value="${id}" ${scenario===id?'selected':''}>${name}</option>`).join('')}</select></div><button class="btn primary" id="verify">모의 적용 검증</button><div id="sdk-result">${snapshot?`<p class="sdk-success">✓ 설정 검증·적용 완료 (모의)</p><p class="hint">${esc(snapshot.id)} · ${esc(snapshot.version)}<br>아래 값은 검증 시 고정됐습니다. 이후 편집과 분리됩니다.</p><details open><summary>실제 적용값</summary><pre>${pretty(snapshot.configs)}</pre></details>`:'<p class="hint">검증 후 고정된 적용값을 표시합니다.</p>'}</div></div></section></div><details class="sdk-details" open><summary>A2A 요청 미리보기</summary><p class="hint">Agent Card의 JSONRPC endpoint로 보낼 요청입니다. 아래 헤더와 metadata.kpap을 함께 사용합니다.</p><pre id="request-preview">${pretty(requestPreview())}</pre></details>`:loading?'<p role="status">예제 조회 중…</p>':''}<details class="sdk-details"><summary>SDK 응답 가져오기 · 그래프 JSON</summary><p class="hint">GET /agents/{agentId}/graph의 응답을 붙여넣으세요. 유효한 응답만 적용하며 기존 초안은 새 그래프의 기본값으로 교체합니다. 이 데모는 임의 서버에 연결하지 않습니다.</p><label for="graph-json">그래프 응답</label><textarea id="graph-json" rows="12" spellcheck="false">${esc(importText)}</textarea><button class="btn" id="import" ${loading?'disabled':''}>검증 후 그래프 표시</button><label class="btn">JSON 파일 선택<input id="graph-file" type="file" accept=".json,application/json"></label></details><details class="sdk-details"><summary>Agent Card · 확장 지원 선언</summary><p class="hint">아래 URL은 설명용 example.com 주소입니다. 실제 연결 시 kpap 서버가 등록된 주소·권한을 확인합니다.</p><pre>${pretty(card||{})}</pre></details>`;
}
app.addEventListener('click',e=>{const node=e.target.closest('[data-node]');if(node){selected=node.dataset.node;render();return;}switch(e.target.id){case'reload':loadExample();break;case'restore':configs[selected]=C.clone(graphSpec.nodes.find(n=>n.id===selected).config||{});contractError='';render();break;case'import':try{if(importText.length>262144)throw new Error('응답은 256 KiB 이하로 입력하세요.');applyGraph(JSON.parse(importText));}catch(err){contractError=[err.code,err.path,err.message].filter(Boolean).join(' · ');}render();break;case'verify':try{const req=C.buildRequest(graphSpec,configs,input,crypto.randomUUID());if(scenario==='version')req.body.params.metadata.kpap.graphVersion='stale';if(scenario==='extension')delete req.headers['A2A-Extensions'];const applied=C.accept(graphSpec,req,()=>scenario!=='permission');snapshot={id:'snapshot-'+crypto.randomUUID(),version:graphSpec.version,configs:applied,request:req};contractError='';}catch(err){snapshot=null;contractError=[err.code,err.path,err.message].join(' · ');}render();break;}});
app.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('[data-node]')){e.preventDefault();selected=e.target.dataset.node;render();}});
app.addEventListener('input',e=>{if(e.target.id==='graph-json')importText=e.target.value;if(e.target.id==='sdk-input'){input=e.target.value;const p=document.querySelector('#request-preview');if(p)p.innerHTML=pretty(requestPreview());}});
app.addEventListener('change',async e=>{const x=e.target;if(x.id==='scenario'){scenario=x.value;return;}if(x.id==='graph-file'){try{const f=x.files[0];if(!f)return;if(f.size>262144)throw new Error('파일은 256 KiB 이하로 선택하세요.');importText=await f.text();document.querySelector('#graph-json').value=importText;}catch(err){contractError=err.message;render();}return;}if(!x.dataset.path)return;try{const path=JSON.parse(x.dataset.path),n=graphSpec.nodes.find(n=>n.id===selected);if(!(n.editable||[]).includes(path[0]))throw new Error('읽기 전용 설정입니다.');let v=x.dataset.json?JSON.parse(x.value):x.type==='number'?Number(x.value):x.type==='checkbox'?x.checked:x.value;const next=C.clone(configs);let target=next[selected];for(const k of path.slice(0,-1))target=target[k];target[path.at(-1)]=v;C.buildRequest(graphSpec,next,input||'검증');configs=next;contractError='';}catch(err){contractError=[err.code,err.path,err.message].filter(Boolean).join(' · ');}render();});
loadExample();
